using Microsoft.EntityFrameworkCore;
using System.Text;
namespace Society.Api;
public static class CommunityMediaEndpoints {
 public static void Map(RouteGroupBuilder api){var t=api.MapGroup("/societies/{tenant:guid}/community").RequireAuthorization().RequireRateLimiting("community");
 t.MapPost("/media",async(Guid tenant,Guid resource,string kind,HttpRequest request,AppDb db,Access a,CommunityService s,IObjectStore storage)=>{await Edit(tenant,resource,kind,s,a);if(request.ContentLength is null or >20971520)throw new DomainException("Media must be no larger than 20 MB");if(await db.Set<CommunityMedia>().CountAsync(m=>m.TenantId==tenant&&m.ResourceId==resource&&m.ResourceKind==kind)>=12)throw new DomainException("Up to twelve media items are allowed");using var output=new MemoryStream();await request.Body.CopyToAsync(output);var bytes=output.ToArray();var type=request.ContentType?.Split(';')[0]??"";if(type=="image/png")bytes=AssetEndpoints.SanitizePng(bytes);else if(type=="application/pdf"){if(bytes.Length>2097152||bytes.Length<12||!Encoding.ASCII.GetString(bytes.Take(5).ToArray()).StartsWith("%PDF-")||!Encoding.ASCII.GetString(bytes.TakeLast(1024).ToArray()).Contains("%%EOF"))throw new DomainException("Invalid PDF attachment");}else if(type=="video/mp4"){if(bytes.Length<24||Encoding.ASCII.GetString(bytes,4,4)!="ftyp"||!new[]{"isom","mp41","mp42","avc1","M4V ","iso2"}.Contains(Encoding.ASCII.GetString(bytes,8,4)))throw new DomainException("Use a standard MP4 video");}else throw new DomainException("Supported media: sanitized PNG, PDF attachment or MP4 video");var name=request.Headers["X-Filename"].ToString();if(name.Length>160)name=name[..160];var media=new CommunityMedia{TenantId=tenant,ResourceId=resource,ResourceKind=kind,ContentType=type,Name=Path.GetFileName(name),Length=bytes.Length,Sort=await db.Set<CommunityMedia>().CountAsync(m=>m.TenantId==tenant&&m.ResourceId==resource&&m.ResourceKind==kind)};await storage.Put(tenant,media.Id,bytes);db.Add(media);await Invalidate(tenant,resource,kind,db);a.Audit(tenant,"community.media.uploaded",media.Id);await db.SaveChangesAsync();return Results.Ok(media);});
 t.MapGet("/media/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s,IObjectStore storage)=>{var m=await db.Set<CommunityMedia>().SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id)??throw new AccessDeniedException();if(m.ResourceKind=="Post")await s.Post(tenant,m.ResourceId);else await s.Event(tenant,m.ResourceId);return m.ContentType=="application/pdf"?Results.File(storage.Open(tenant,id),m.ContentType,string.IsNullOrWhiteSpace(m.Name)?"attachment.pdf":m.Name):Results.File(storage.Open(tenant,id),m.ContentType,enableRangeProcessing:true);});
 t.MapPut("/media/{id:guid}",async(Guid tenant,Guid id,MediaOrder r,AppDb db,Access a,CommunityService s)=>{var m=await db.Set<CommunityMedia>().SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id)??throw new AccessDeniedException();await Edit(tenant,m.ResourceId,m.ResourceKind,s,a);if(r.Sort is <0 or >12)throw new DomainException("Invalid media order");m.Sort=r.Sort;m.Cover=r.Cover;if(r.Cover)await db.Set<CommunityMedia>().Where(x=>x.TenantId==tenant&&x.ResourceId==m.ResourceId&&x.ResourceKind==m.ResourceKind&&x.Id!=id).ExecuteUpdateAsync(x=>x.SetProperty(p=>p.Cover,false));await Invalidate(tenant,m.ResourceId,m.ResourceKind,db);a.Audit(tenant,"community.media.updated",id);await db.SaveChangesAsync();return Results.NoContent();});
 t.MapDelete("/media/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a,CommunityService s)=>{var m=await db.Set<CommunityMedia>().SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id)??throw new AccessDeniedException();await Edit(tenant,m.ResourceId,m.ResourceKind,s,a);await Invalidate(tenant,m.ResourceId,m.ResourceKind,db);db.Remove(m);a.Audit(tenant,"community.media.removed",id);await db.SaveChangesAsync();return Results.NoContent();});
 }
 static async Task Edit(Guid tenant,Guid id,string kind,CommunityService s,Access a){if(kind=="Post"){var p=await s.Post(tenant,id);if(p.AuthorId!=a.UserId)throw new AccessDeniedException();if(p.Status=="Removed")throw new AccessDeniedException();}else if(kind=="Event"){var e=await s.Event(tenant,id);await a.Require(tenant,"events.manage",e.UnitId);}else throw new DomainException("Unknown media owner");}
 static async Task Invalidate(Guid tenant,Guid id,string kind,AppDb db){if(kind=="Post"){var p=await db.Set<ActivityPost>().SingleAsync(p=>p.TenantId==tenant&&p.Id==id);p.Status="Draft";p.Stage=0;p.PublishedAt=null;p.Revision++;}else{var e=await db.Set<CommunityEvent>().SingleAsync(e=>e.TenantId==tenant&&e.Id==id);e.Status="Draft";e.Stage=0;e.PublishedAt=null;e.Revision++;}}
}
public record MediaOrder(int Sort,bool Cover);
